; cost.asm -- chapter 7: a byte from a register and from memory
; generated by gen07.py
        INCLUDE "msx.inc"
        OUTPUT "cost.rom"
        ORG $4000
        CART_HEADER init
VARS    EQU RAM_START + $100    ; the program's variables: the code is in ROM
RESULTS EQU RAM_START          ; what the program found: the debugger reads it here
init:   di
        ld sp, SYS_AREA
        ld hl, RAM_START
        ld b, $42
t0:
        ld a, b
t1:
        ld a, (hl)
t2:
        ld a, (RAM_START)
t3:
        ld a, ($4000)
t4:
        ld (hl), a
t5:
        ld (RAM_START), a
t6:
stop:   jr stop
        ds $8000 - $, $FF       ; pad the cartridge to 16 KB
        ASSERT $ == $8000
